297	// ════════════════════════════════════════════════════════════════════════════
298	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, R2.3). Compiled only under
299	//  the wgmma token; the scalar path above is untouched.
300	// ════════════════════════════════════════════════════════════════════════════
301	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
302	
303	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
304	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
305	// path's asymmetric setmaxnreg (dealloc<32> on WG0) — that would STARVE the MMA
306	// warpgroup (WG0 issues the wgmma; a 128-wide accumulator needs 64 fp32 regs/
307	// thread). The validated selftest ran no split; we match it.
308	#define SG_TC_MEGA_BLOCK 256
309	
310	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
311	//    + the 256-float reduction slot. 16B-aligned. N = SG_TUNED_TILE_N. The 9 dW
312	//    specs live here too (identical for all threads → shared, not per-thread
313	//    stack: keeps the launch's local-memory reservation small so the persistent
314	//    kernel places on a memory-tight GPU). ──
315	struct DecTcSmem {
316	    // kDecTcStages A(64×16) + kDecTcStages B(N×16) bf16 tiles — the GEMM K-loop
317	    // double-buffer ring (slot s at sA + s*64*16 / sB + s*N*16). At S=2 + N=128
318	    // the ring is 2·(2KB+4KB)=12KB; DecTcSmem total ~13.5KB ≪ the 48KB static cap.
319	    __nv_bfloat16 sA[dectc::kDecTcStages * 64 * 16];
320	    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
321	    float red[256];
322	    dectc::DecDwSpec spec[9];
323	};
